import{_ as s,c as t,o as n,j as a,a as r}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"汉上易传卷十","description":"汉上易传 - 汉上易传卷十","frontmatter":{"title":"汉上易传卷十","description":"汉上易传 - 汉上易传卷十"},"headers":[],"relativePath":"zh/classics/hanshang/011.md","filePath":"zh/classics/hanshang/011.md"}'),c={name:"zh/classics/hanshang/011.md"};function o(l,e,i,d,h,p){return n(),t("div",null,[...e[0]||(e[0]=[a("h1",{id:"汉上易传卷十",tabindex:"-1"},[r("汉上易传卷十 "),a("a",{class:"header-anchor",href:"#汉上易传卷十","aria-label":"Permalink to “汉上易传卷十”"},"​")],-1),a("p",null,"文王作易，以乾、坤、坎、离为上篇之用，以艮、兑、震、巽为下篇之用。上篇终于坎、离，下篇终于既、济、未济、颐、大过、小过、中孚，为二篇之正。乾、坤者，易之本；坎、离者，乾、坤之用。离肖乾，坎肖坤，中孚肖乾，小过肖坤，颐肖离，大过肖坎。既、济坎、离之交，未济坎、离之合。坎、离所以为乾、坤用者，得天地之中也。斯圣人酬酢不倚，千变万化不离乎其中欤？康节曰：至哉，文王之作易也，其得天地之用乎？至夫子序卦，然后明生生不穷，而天地之蕴尽矣。故太玄准之以玄图有天地，然后万物生焉。盈天地之间者唯万物，故受之以屯。屯者，盈也。屯者，物之始生也。物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。物稚不可不养也，故受之以需。需者，饮食之道也。饮食必有讼，故受之以讼。讼必有众起，故受之以师。师者，众也。众必有所比，故受之以比。比者，比也。比必有所畜，故受之以小畜。物畜然后有礼，故受之以履。履而泰然后安、故受之以泰。泰者，通也。物不可以终通、故受之以否。物不可以终否、故受之以同人。与人同者、物必归焉、故受之以大有。有大者不可以盈、故受之以谦。有大而能谦必豫、故受之以豫。豫必有随、故受之以随。以喜随人者必有事、故受之以蛊。蛊者，事也。有事而后可大，故受之以临。临者，大也。物大然后可观，故受之以观。可观而后有所合，故受之以噬嗑。嗑者，合也。物不可以苟合而巳，故受之以贲。贲者，饰也。致饰然后亨则尽矣，故受之以剥。剥者，剥也。物不可以终尽，剥，穷上反下、故受之以复。复则不妄矣、故受之以无妄。有无妄然后可畜、故受之以大畜。物畜然后可养、故受之以颐。颐者、养也。不养则不可动、故受之以大过。物不可以终过、故受之以坎。坎者、陷也。陷必有所丽、故受之以离。离者、丽也。上篇以乾、坤、坎、离为用，天地之生万物也，而有艮、兑、震、巽焉，天地万物具而人道备矣。下篇以艮、兑、震、巽为用，有万物而后男女夫妇也，而有乾、坤、坎、离焉，人道备而天地万物备矣。故曰三才同科，厚薄相劘。韩康伯不领此旨，谓岂有天道人事偏于上下哉。读序卦而不察者也。云行雷动，动必满盈，故曰屯者，盈也。震者，物之始生，坎者，难也，故曰屯者物之始生也。蒙，冥昧也。物生者必始于冥昧，勾萌胎夘是也。故次之以蒙。蒙，童蒙也。物如此稚也，物稚而无以养之，则夭阏不遂。蓄德养才者亦然，故次之以需、震、坎为酒，兑为口。有饮食之道，饮食所以养也。饮食必有讼。乾糇以愆，豕酒生祸。有血气者必有争心。故次之以讼。讼者两辞，必以众起，故次之以师。师，众也。众不能以治众，治众者至寡也。众之所以比，执一以御之，则众治矣。故以次之以比。比，相亲比也。彼来比我，我必蓄之，故次之以小畜。物畜聚，然后有上下尊卑之等。上下尊卑，所谓礼也，故次之以履。礼者，履而行之者也。所履者，君子大道，则其心泰然而安，故次之以泰。泰者，万物通也。物终通则无节，故次之以否。否，塞也。物终否则乖异不相为用，故次之以同人。同人者，与人同也。与人同者，物必归焉。舜大王是巳，故次之以大有。认物之归为已有者必骄，骄则亢满，大复为累矣。有大者不可盈也，故次之以谦。物归之矣，又持之以谦，犹富而守之以俭，岂不有余裕哉。有大而能谦者，必暇豫也，故次之以豫事。豫立则动而不跲，众必随之，故次之以随。好上人者，人之情也。以喜随人，必有所事。臣事君，子事父，妇事夫，弟子事师，非乐于所事者，其肯随乎？故次之以蛊。蛊者，事坏而后有事者也。韩康伯曰：可大之业，由事以生。临者，以大临小也。故次之以临。观者，自下观上，物大然后可观，是以王尚大，故次之以观。在上而无可观，则在下引而去矣。非可观，其能有合乎？故次之以噬嗑。噬嗑者，噬而合者也。物不可以苟合，苟合者，其终则离，必致饰焉，故次之以贲。贲、阴阳相饰也。致饰然后物亨。亨则尽矣。无以复加、故次之以剥。剥者、剥也。此商周之末、所以不胜其弊、文之末流也。物穷则反、不可终尽。剥阳穷于上而终反于下、故次之以复。复天理则无妄。无妄则其动也天、故次之以无妄。然后物物循理、乃可大畜，故次之以大畜。前曰比，必有所畜者，比而后畜，其畜也小，故次之以小畜。物能畜止，然后可养，虽养虎不外是也，故次之以颐。颐者，观人之养也，求口实以自养也。圣人养贤，贤人养德，不养之则不能动。大过者，动而大过乎物也，故次之以大过。而大过六爻，皆以居安不动为忌。君子之所以过者，时也。过而不巳则失中，失中则陷没。坎，陷也。陷必有所附丽，乃能出险，故次之以离。离，丽也。一本云：丽必有所感，故次之以咸。咸，感也。",-1),a("p",null,"有天地然后有万物，有万物然后有男女，有男女然后有夫妇。有夫妇然后有父子，有父子然后有君臣，有君臣然后有上下，有上下然后礼义有所错。夫妇之道，不可以不久也，故受之以恒。恒者，久也。物不可以久居其所，故受之以遁。遁者，退也，故受之以大壮。物不可以终壮，故受之以晋。晋者，进也。进必有所伤，故受之以明夷。夷者，伤也。伤于外者必反于家，故受之以家人。家道穷必乖，故受之以睽。聧者，乖也。乖必有难，故受之以蹇。蹇者，难也。物不可以终难，故受之以解。解者，缓也。缓必有所失，故受之以损。损而不已，必益，故受之以益。益而不巳，必决，故受之以夬。夬者，决也。决必有遇，故受之以姤。姤者，遇也。物相遇而后聚，故受之以萃。萃者，聚也。聚而上者谓之升，故受之以升。升而不巳必困，故受之以困。困乎上者必反下，故受之以井。井道不可不革，故受之以革。革物者莫若鼎，故受之以鼎。主器者莫若长子，故受之以震。震者，动也。物不可以终动，止之，故受之以艮。艮者，止也。物不可以终止，故受之以渐。渐者，进也。进必有所归，故受之以归。妹得其所归者必大，故受之以丰。丰者，大也。穷大者必失其居，故受之以旅。旅而无所容，故受之以巽。巽者，入也。入而后说之，故受之以兑。兑者，说也。说而后散之，故受之以涣。涣者，离也。物不可以终离，故受之以节。节而信之，故受之以中孚。有其信者必行之，故受之以小过。有过物者必济，故受之以既。济物不可穷也，故受之以未济终焉。君子之道，造端乎夫妇，久于其道而后化，故次之以恒。恒，久也。进退升降，与时消息，不可久居其所而不去，故次之以遁。君子，万物之主，终遁而不反，天地闭塞，故次之以大壮。大者壮则小者羸，可进之时也，故次之以晋。晋，日出地而进于昼也，进而不巳，伤之者至，故次之以明夷。明夷，日在地中，明有所伤也。物无不反其本者，疾痛则呼其父母，伤于外者，未有不反于内，故次之以家人。家人，内也。治家者刚柔有节，过刚则厉，过柔则渎，无节则道穷而亲族乖离，故次之以聧。聧者，水火乖也。乖离则情不通而难生，故次之以蹇。蹇者，行有难也。难极必解，无终难之理，故次之以解。解蹇，难解也。难解则舒缓。解者，蹇之反五，退而居二，缓也。缓则宽弛，必有所失，故次之以损。损，减也。减下而益上，有失之象。消久则息，损而不巳者必益，损益相反也，故次之以益。益久则盈，盈则必决，堤防是巳，故次之以夬。夬者，阳决阴也。决则分，分则相遇，故次之以姤。姤者，阴出而与阳相遇也。物以类相从，遇而后聚，非其类，虽同居不相遇，故次之以萃。萃，二阳聚也。物相崇聚，其势必升，积土是已，故次之以升。升者，聚而上之谓也。升而不知反，则力穷而困，故次之以困。困乎上者，必反乎下，山剥是巳，故次之以井。井，在下者也。井久则秽浊不食。治井之道，革去其害井者而己。三代之革，其礼相困，损益可知也，故次之以革。鼎之革物，以水济火而熟之。革物者莫如鼎，故次之以鼎。鼎，器也。主宗庙之器者莫如长子。震，长子也，故次之以震。震者，阳动于下也。物不可以终动，动极则止，故止之。艮者，一阳止于上也，故次之以艮。物不可以终止，止极则动，故次之以渐。渐者，进有序也，进必有所归，盈科之水是也，故次之以归妹。归妹者，女之归也。得其所归者必大，海善下是也，故次之以丰。丰，大也。前曰与人同者，物必归焉，故受之以大有。此曰得其归者必大，大有次同人者，处大之道也。丰次归妹者，致大之道也。巳大矣，而又穷之，必至于无所寄托而失其所居之常，非特大名大位然也。学亦如是，故次之以旅。旅者，君子之穷也。旅卦以柔顺谦下为吉，否则无所容矣，故次之以巽。巽者，阴入于阳之下也。天地之泽，万物礼义之说，人心不入则不说，故次之以兑。兑者，说见于外也。说之而后散之，则说道不劳，无所不说矣，故次之以涣。涣者，险难离散也。离者必聚，散者必合，物无终离者也。聚者离之节，合者，散之节。节之则无离散，故次之以节。天地之节，不可以不信，不信则无以成万物，而况于人乎？饮食起居，身之节也。不信则致疾。尊卑长幼，家之节也，不信则召乱，故次之以中孚。中孚，信也。行者，足相过也。小过以阴过，阳有行之象，有其信者，必行中无所疑也，故次之以小过。物各有量，不过则不能相济，所过大则其济亦大，是以智周万物，然后道济天下，故次之以既济，而止复入于未济。物之相生，终不可穷，故以未济终篇焉。周易序卦传第十。",-1)])])}const f=s(c,[["render",o]]);export{_ as __pageData,f as default};
